def is_sublist(l, s):
    # Check if the sublist is empty, return True if it is
    if not s:
        return True
    # Check if the sublist is longer than the list, return False if it is
    elif len(s) > len(l):
        return False
    # Iterate through the list to check for the presence of the sublist
    else:
        for i in range(len(l)):
            # If the first element of the sublist matches the current element in the list
            if l[i] == s[0]:
                n = 1
                # Check the subsequent elements
                while (n < len(s)) and (l[i+n] == s[n]):
                    n += 1
                # If all elements match, return True
                if n == len(s):
                    return True
    # If no match is found, return False
    return False

