def max_sum(arr):
    n = len(arr)
    # Initialize the list to store the maximum sum of increasing subsequence
    inc = arr.copy()
    # Initialize the list to store the maximum sum of decreasing subsequence
    dec = arr.copy()

    # Calculate maximum sum of increasing subsequence for each element
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and inc[i] < inc[j] + arr[i]:
                inc[i] = inc[j] + arr[i]

    # Calculate maximum sum of decreasing subsequence for each element
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if arr[i] > arr[j] and dec[i] < dec[j] + arr[i]:
                dec[i] = dec[j] + arr[i]

    # Find the maximum sum of bitonic subsequence
    max_bitonic_sum = 0
    for i in range(n):
        max_bitonic_sum = max(max_bitonic_sum, inc[i] + dec[i] - arr[i])

    return max_bitonic_sum

def is_Sum_Of_Powers_Of_Two(n):
    # Loop until n becomes 0
    while n:
        # If n is odd and greater than 1, it cannot be represented as sum of non-zero powers of 2
        if n & 1 and n > 1:
            return False
        # Right shift n by 1 to check the next bit
        n >>= 1
    # If the loop completes, n can be represented as sum of non-zero powers of 2
    return True

