def max_product(arr):
    n = len(arr)
    # Initialize the list to store the maximum product subsequence ending at each index
    mp = arr[:]

    # Iterate through the array to fill the mp list
    for i in range(1, n):
        for j in range(i):
            # Check if the current element is greater than the previous element
            # and if multiplying them gives a larger product than the current max product
            if arr[i] > arr[j] and mp[i] < mp[j] * arr[i]:
                mp[i] = mp[j] * arr[i]

    # Return the maximum value from the mp list
    return max(mp)

